INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist eine Kosten-Nutzen-Analyse immer erforderlich, um die Wirtschaftlichkeit eines IT-Projekts zu bewerten?', 2, '[{"text": "Nein", "correct": true, "because": "Alternative Methoden wie ROI können genutzt werden"}, {"text": "Ja", "correct": false, "because": "Sie ist hilfreich, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können qualitative Faktoren in einer Kosten-Nutzen-Analyse vollständig ignoriert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzen wie Zufriedenheit ist oft nicht monetär messbar"}, {"text": "Ja", "correct": false, "because": "Qualitative Aspekte beeinflussen die Bewertung"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen in einer Kosten-Nutzen-Analyse alle zukünftigen Kosten exakt vorhergesagt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Schätzungen sind üblich, Präzision ist oft unrealistisch"}, {"text": "Ja", "correct": false, "because": "Ungewissheit ist akzeptiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Nutzen in einer Kosten-Nutzen-Analyse immer monetär messbar?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzen kann z. B. Zeitersparnis oder Imagegewinn sein"}, {"text": "Ja", "correct": false, "because": "Nicht alle Vorteile sind finanziell quantifizierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Kosten-Nutzen-Analyse ohne Berücksichtigung von Risiken verlässlich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Risiken beeinflussen Kosten und Nutzen"}, {"text": "Ja", "correct": false, "because": "Ohne Risikoanalyse fehlt Realismus"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist in einer Kosten-Nutzen-Analyse entscheidend, um langfristige Wirtschaftlichkeit zu bewerten?', 3, '[{"text": "Lebenszykluskosten", "correct": true, "because": "Umfasst Anschaffung, Betrieb und Entsorgung"}, {"text": "Kurzfristige Einsparungen", "correct": false, "because": "Vernachlässigt Folgekosten"}, {"text": "Anzahl der Nutzer", "correct": false, "because": "Sekundär zur Kostenstruktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element der Kosten-Nutzen-Analyse ist am schwierigsten exakt zu quantifizieren?', 2, '[{"text": "Indirekter Nutzen", "correct": true, "because": "Z. B. Mitarbeiterzufriedenheit ist schwer messbar"}, {"text": "Anschaffungskosten", "correct": false, "because": "Direkt kalkulierbar"}, {"text": "Betriebskosten", "correct": false, "because": "Basieren auf Erfahrungswerten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft am besten, Unsicherheiten in einer Kosten-Nutzen-Analyse zu berücksichtigen?', 3, '[{"text": "Szenarioanalyse", "correct": true, "because": "Prüft verschiedene Zukunftsszenarien"}, {"text": "Lineare Kostenprognose", "correct": false, "because": "Ignoriert Variablen"}, {"text": "Historische Datenextrapolation", "correct": false, "because": "Vernachlässigt Veränderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel einer Kosten-Nutzen-Analyse in einem IT-Projekt?', 2, '[{"text": "Vergleich von Aufwand und Ertrag", "correct": true, "because": "Bewertet Wirtschaftlichkeit"}, {"text": "Maximierung der Funktionalität", "correct": false, "because": "Nicht primäres Ziel"}, {"text": "Reduktion der Entwicklungszeit", "correct": false, "because": "Zeit ist sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann die Ergebnisse einer Kosten-Nutzen-Analyse am stärksten verfälschen?', 3, '[{"text": "Unrealistische Annahmen", "correct": true, "because": "Verzerren Kosten- und Nutzenprognosen"}, {"text": "Zu detaillierte Dokumentation", "correct": false, "because": "Detailtiefe schadet nicht"}, {"text": "Hohe Anzahl an Variablen", "correct": false, "because": "Komplexität ist manageable"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Kostenarten sollten in einer Kosten-Nutzen-Analyse berücksichtigt werden?', 4, '[{"text": "Direkte Kosten", "correct": true, "because": "Z. B. Hardwareanschaffung"}, {"text": "Indirekte Kosten", "correct": true, "because": "Z. B. Schulungen"}, {"text": "Kosten für Werbekampagnen", "correct": false, "because": "Projektfremd"}, {"text": "Folgekosten", "correct": true, "because": "Z. B. Wartung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nutzenarten können in einer Kosten-Nutzen-Analyse einfließen?', 3, '[{"text": "Zeitersparnis", "correct": true, "because": "Erhöht Effizienz"}, {"text": "Umsatzsteigerung", "correct": true, "because": "Direkter finanzieller Vorteil"}, {"text": "Maximale Softwarefeatures", "correct": false, "because": "Kein direkter Nutzen"}, {"text": "Nutzerzufriedenheit", "correct": true, "because": "Langfristiger Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen können bei einer Kosten-Nutzen-Analyse auftreten?', 4, '[{"text": "Schätzung zukünftiger Kosten", "correct": true, "because": "Ungewissheit erschwert Prognosen"}, {"text": "Bewertung immaterieller Vorteile", "correct": true, "because": "Schwer quantifizierbar"}, {"text": "Schnelle Berechnung", "correct": false, "because": "Geschwindigkeit ist kein Problem"}, {"text": "Unvorhergesehene Risiken", "correct": true, "because": "Können Ergebnisse verfälschen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind für eine effektive Kosten-Nutzen-Analyse notwendig?', 3, '[{"text": "Identifikation aller Kosten", "correct": true, "because": "Vollständigkeit ist essenziell"}, {"text": "Bewertung des Nutzens", "correct": true, "because": "Vergleichsgrundlage"}, {"text": "Festlegung der Programmiersprache", "correct": false, "because": "Irrelevant für Analyse"}, {"text": "Risikoabschätzung", "correct": true, "because": "Erhöht Realismus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Genauigkeit einer Kosten-Nutzen-Analyse?', 3, '[{"text": "Qualität der Datenbasis", "correct": true, "because": "Ungenaue Daten verfälschen"}, {"text": "Zeitlicher Horizont", "correct": true, "because": "Langfristigkeit ist schwer prognostizierbar"}, {"text": "Anzahl der Teammitglieder", "correct": false, "because": "Teamgröße ist nicht maßgeblich"}, {"text": "Realistische Annahmen", "correct": true, "because": "Basis für Verlässlichkeit"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine Kosten-Nutzen-Analyse kann auch qualitative Vorteile berücksichtigen. b) Sie ist nur für große Projekte sinnvoll.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualitative Faktoren sind relevant, Nutzen ist projektunabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Kosten-Nutzen-Analyse sollte Risiken ignorieren, um einfach zu bleiben. b) Sie hilft, Investitionsentscheidungen zu rechtfertigen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Risiken sind wichtig, Rechtfertigung ist Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine Kosten-Nutzen-Analyse kann langfristige Einsparungen übersehen. b) Sie erfordert eine Monetarisierung aller Faktoren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Langfristigkeit kann unterschätzt werden, Monetarisierung ist nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Kosten-Nutzen-Analyse ist eine rein finanzielle Bewertung. b) Sie kann durch Szenarien Unsicherheiten abfedern.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Analyse ist breiter, Szenarien erhöhen Robustheit"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine Kosten-Nutzen-Analyse sollte alle Projektphasen abdecken. b) Sie ist unabhängig von der Datenqualität verlässlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Phasen sind relevant, Datenqualität entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');
